<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'

type Candle = { date: string; close: number; open: number; high: number; low: number; volume: number; value?: number }
type Holding = { symbol: string; shares: number; entryPrice: number; stop?: number; target?: number; openedDate?: string; holdingSessions?: number }
type Plan = { symbol: string; action: string; reasons: string[]; entry: number | null; stop: number | null; target: number | null; lots: number; estimatedCost: number; plannedRisk: number; asOf: string | null; expiry: string; strategyVersion: string; rank?: number | null; score?: number | null; eligible?: boolean; avgDailyValue?: number | null; historySessions?: number; rankingReasons?: string[] }
type ScanUniverse = { discovered: number; selected: number; scanned: number; eligible: number; qualified: number; failed: string[]; limit: number; source: string; asOf: string; coverage: string }
type Dashboard = { universe?: ScanUniverse; symbols?: string[]; histories: Record<string, Candle[]>; index: Candle[]; source: { asOf: string; fetchedAt: string; status: string; message: string }; holdings: Holding[]; settings: Record<string, number>; plans: Plan[]; backtest: any }
const page = ref('overview')
const busy = ref('loading')
const error = ref('')
const notice = ref('')
const data = ref<Dashboard | null>(null)
const holdings = ref<Holding[]>([])
const settings = reactive<Record<string, number>>({ cash: 10000000, equity: 10000000, riskPct: .5, maxPositionPct: 25, maxTotalRiskPct: 2, buyFeePct: .15, sellFeePct: .25, slippagePct: .1, minDailyValue: 1000000000, maxPositions: 4, holdingSessions: 15 })
const newHolding = reactive({ symbol: '', shares: 100, entryPrice: 0, stop: 0, target: 0, openedDate: '' })
const showAdvanced = ref(false)
const planFilter = ref('all')
const planQuery = ref('')
const planPage = ref(1)
const pageSize = 15
const journal = ref<any>({ trades: [], alerts: [], monitoring: [] })
const journalBusy = ref(false)
const journalError = ref('')
const tradeNotice = ref('')
const trade = reactive({ symbol: '', side: 'BUY', date: new Date(Date.now() + 7 * 3600000).toISOString().slice(0, 10), shares: 100, price: 0, fee: 0, stop: 0, target: 0, holdingSessions: 0 })
const tradeRequestId = ref('')
const researchSymbol = ref('')
const research = ref<any>(null)
const researchBusy = ref(false)
const researchError = ref('')
const providerAnalysis = computed(() => research.value?.analysis || { status: 'unavailable', asOf: null, output: '', notes: ['Analisa belum tersimpan. Gunakan Ambil data Arjum saat batas pembaruan mengizinkan.'] })
type PromptMode = 'deep-research' | 'starting-plan' | 'daily-check-in'
type PromptPreview = { text: string; generatedAt: string; mode: PromptMode; symbols: string[]; warnings: string[]; includesPortfolio: boolean }
const promptMode = ref<PromptMode>('deep-research')
const promptSymbols = ref<string[]>([])
const promptQuery = ref('')
const includePortfolio = ref(false)
const includeResearch = ref(true)
const promptPreview = ref<PromptPreview | null>(null)
const promptBusy = ref(false)
const promptError = ref('')
const copyNotice = ref('')
const promptTextarea = ref<HTMLTextAreaElement | null>(null)
const promptModes = [
 { id: 'deep-research' as const, title: 'Deep Research', description: 'Bandingkan kandidat, bukti yang mendukung, risiko, dan data yang belum tersedia.' },
 { id: 'starting-plan' as const, title: 'Starting Plan', description: 'Pahami rencana awal dan kesesuaiannya dengan dana serta batas risiko tersimpan.' },
 { id: 'daily-check-in' as const, title: 'Daily Check-in', description: 'Tinjau posisi yang sudah dimiliki dan kondisi keluar dari data terbaru tersimpan.' }
]
const promptChoices = computed(() => availableSymbols.value.filter(s => s.includes(promptQuery.value.trim().toUpperCase())))
const calendarLabel = (status: string) => (({ verified: 'Kalender terverifikasi', unsupported: 'Kalender belum tercakup', 'missing-entry': 'Tanggal beli belum diisi', 'invalid-entry': 'Tanggal beli perlu diperiksa', 'historical-observed': 'Berdasarkan sesi historis tersedia' } as Record<string,string>)[status] || 'Belum tersedia')
const showOpeningHoldings = ref(false)
const researchStatus = (status: string) => (({ available: 'Tersedia', partial: 'Sebagian data', unavailable: 'Belum tersedia', stale: 'Data lama' } as Record<string,string>)[status] || status)
const monitorLabel = (action: string) => (({ HOLD: 'Pertahankan sesuai rencana', SELL: 'Periksa kondisi keluar', WAIT: 'Tunggu data yang memadai' } as Record<string,string>)[action] || action)
const unseenAlerts = computed(() => journal.value.alerts.filter((a: any) => !a.acknowledgedAt))
const tradeSymbols = computed(() => trade.side === 'SELL' ? holdings.value.map(h => h.symbol) : availableSymbols.value)
const nav = [{ id: 'overview', icon: '◫', label: 'Ringkasan' }, { id: 'plans', icon: '↗', label: 'Trade planner' }, { id: 'holdings', icon: '▤', label: 'Portofolio' }, { id: 'research', icon: '◎', label: 'Riset saham' }, { id: 'prompts', icon: '▧', label: 'Prompt manual' }, { id: 'backtest', icon: '⌁', label: 'Backtest' }]
const idr = (n: any) => Number.isFinite(Number(n)) && n !== null ? new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(n)) : '—'
const num = (n: any) => Number.isFinite(Number(n)) && n !== null ? new Intl.NumberFormat('id-ID', { maximumFractionDigits: 2 }).format(Number(n)) : '—'
const date = (s?: string | null) => s ? new Date(s.length === 10 ? s + 'T12:00:00+07:00' : s).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Asia/Jakarta' }) : 'Belum tersedia'
const dateTime = (s?: string | null) => s ? new Date(s).toLocaleString('id-ID', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Jakarta' }) + ' WIB' : 'Belum tersedia'
const indexRows = computed(() => [...(data.value?.index || [])].sort((a, b) => a.date.localeCompare(b.date)))
const latestIndex = computed(() => indexRows.value.at(-1))
const indexChange = computed(() => { const rows = indexRows.value; return rows.length > 1 ? (rows.at(-1)!.close / rows.at(-2)!.close - 1) * 100 : null })
const plans = computed(() => data.value?.plans || [])
const availableSymbols = computed(() => [...new Set([...(data.value?.symbols || Object.keys(data.value?.histories || {})), ...holdings.value.map(h => h.symbol)])].sort())
const filteredPlans = computed(() => plans.value.filter(p => (!planQuery.value || p.symbol.includes(planQuery.value.trim().toUpperCase())) && (planFilter.value === 'all' || (planFilter.value === 'qualified' && p.rank != null) || (planFilter.value === 'held' && holdings.value.some(h => h.symbol === p.symbol)))))
const totalPlanPages = computed(() => Math.max(1, Math.ceil(filteredPlans.value.length / pageSize)))
const visiblePlans = computed(() => filteredPlans.value.slice((planPage.value - 1) * pageSize, planPage.value * pageSize))
watch([planFilter, planQuery, plans], () => { planPage.value = 1 })
const compactIDR = (value: number | null | undefined) => value == null || !Number.isFinite(value) ? '—' : new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', notation: 'compact', maximumFractionDigits: 1 }).format(value)
const buyCount = computed(() => plans.value.filter(p => p.action === 'BUY').length)
const reserved = computed(() => plans.value.filter(p => p.action === 'BUY').reduce((sum, p) => sum + (p.estimatedCost || 0), 0))
const plannedRisk = computed(() => plans.value.filter(p => p.action === 'BUY').reduce((sum, p) => sum + (p.plannedRisk || 0), 0))
const activeTitle = computed(() => nav.find(n => n.id === page.value)?.label)
const report = computed(() => data.value?.backtest)
const testPeriod = ref('holdout')
const testResult = computed(() => report.value?.[testPeriod.value])
const performancePaths = computed(() => { const curve = testResult.value?.equityCurve || []; if (curve.length < 2) return { strategy: '', benchmark: '' }; const values = curve.flatMap((p: any) => [p.equity, p.benchmarkEquity]).filter(Number.isFinite); const min = Math.min(...values), max = Math.max(...values); const path = (key: string) => curve.map((p: any, i: number) => `${i ? 'L' : 'M'}${i / (curve.length - 1) * 760},${168 - (p[key] - min) / (max - min || 1) * 156}`).join(' '); return { strategy: path('equity'), benchmark: path('benchmarkEquity') } })
function chartPath(values: number[], w = 760, h = 180) { if (values.length < 2) return ''; const min = Math.min(...values), max = Math.max(...values); return values.map((v, i) => `${i ? 'L' : 'M'}${i / (values.length - 1) * w},${h - 12 - (v - min) / (max - min || 1) * (h - 24)}`).join(' ') }
const indexPath = computed(() => chartPath(indexRows.value.slice(-65).map(r => r.close)))
async function request(url: string, body?: unknown) { const r = await fetch(url, body ? { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) } : undefined); const payload = await r.json(); if (!r.ok) throw new Error(payload.statusMessage || payload.message || 'Permintaan gagal. Coba lagi.'); return payload }
function applyDashboard(payload: Dashboard) { data.value = payload; Object.assign(settings, { holdingSessions: 15 }, payload.settings); holdings.value = payload.holdings || [] }
async function load() { busy.value = 'loading'; error.value = ''; try { applyDashboard(await request('/api/dashboard')); await loadJournal() } catch (e: any) { error.value = e.message } finally { busy.value = '' } }
async function loadJournal() { invalidatePrompt(); journalBusy.value = true; journalError.value = ''; try { journal.value = await request('/api/journal') } catch (e: any) { journalError.value = e.message } finally { journalBusy.value = false } }
async function recordTrade() {
 invalidatePrompt()
 journalBusy.value = true; journalError.value = ''; tradeNotice.value = ''
 try {
  tradeRequestId.value ||= crypto.randomUUID()
  const payload = await request('/api/journal', { id: tradeRequestId.value, symbol: trade.symbol, side: trade.side, date: trade.date, shares: trade.shares, price: trade.price, fee: trade.fee, ...(trade.side === 'BUY' && trade.stop > 0 ? { stop: trade.stop } : {}), ...(trade.side === 'BUY' && trade.target > 0 ? { target: trade.target } : {}), ...(trade.side === 'BUY' && !holdings.value.some(h => h.symbol === trade.symbol) && trade.holdingSessions > 0 ? { holdingSessions: trade.holdingSessions } : {}) })
  journal.value = payload
  tradeNotice.value = 'Transaksi tercatat. Posisi dan dana tersedia telah diperbarui. Tidak ada pesanan yang dikirim ke broker.'
  Object.assign(trade, { symbol: '', shares: 100, price: 0, fee: 0, stop: 0, target: 0, holdingSessions: 0 })
  tradeRequestId.value = ''
  if (payload.portfolio) { Object.assign(settings, payload.portfolio.settings); holdings.value = payload.portfolio.holdings }
  applyDashboard(await request('/api/dashboard'))
 } catch (e: any) { journalError.value = e.message } finally { journalBusy.value = false }
}
async function acknowledgeAlert(id: string) { journalBusy.value = true; journalError.value = ''; try { journal.value = await request('/api/alerts', { id }) } catch (e: any) { journalError.value = e.message } finally { journalBusy.value = false } }
let researchSequence = 0
async function loadResearch(refreshData = false) {
 if (!researchSymbol.value) return
 if (refreshData) invalidatePrompt()
 const sequence = ++researchSequence
 researchBusy.value = true; researchError.value = ''; research.value = null
 try { const result = await request(refreshData ? '/api/research' : `/api/research?symbol=${encodeURIComponent(researchSymbol.value)}`, refreshData ? { symbol: researchSymbol.value } : undefined); if (sequence === researchSequence) research.value = result } catch (e: any) { if (sequence === researchSequence) researchError.value = e.message } finally { if (sequence === researchSequence) researchBusy.value = false }
}
function inspectSymbol(symbol: string) { researchSymbol.value = symbol; page.value = 'research' }
let promptSequence = 0
function invalidatePrompt() { promptSequence++; promptPreview.value = null; promptBusy.value = false; copyNotice.value = ''; promptError.value = '' }
watch([promptMode, promptSymbols, includePortfolio, includeResearch], invalidatePrompt, { deep: true, flush: 'sync' })
watch([data, settings, holdings, research, journal], invalidatePrompt, { deep: true, flush: 'sync' })
function choosePromptSymbol(symbol: string) {
 if (promptSymbols.value.includes(symbol)) promptSymbols.value = promptSymbols.value.filter(s => s !== symbol)
 else if (promptSymbols.value.length < 10) promptSymbols.value = [...promptSymbols.value, symbol]
}
async function generatePrompt() {
 const sequence = ++promptSequence
 promptBusy.value = true; promptError.value = ''; copyNotice.value = ''; promptPreview.value = null
 try {
  const preview = await request('/api/prompts', { mode: promptMode.value, symbols: promptMode.value === 'daily-check-in' ? [] : [...promptSymbols.value], includePortfolio: includePortfolio.value, includeResearch: includeResearch.value })
  if (sequence === promptSequence) promptPreview.value = preview
 } catch (e: any) { if (sequence === promptSequence) promptError.value = e.message }
 finally { if (sequence === promptSequence) promptBusy.value = false }
}
async function copyPrompt() {
 if (!promptPreview.value) return
 const text = promptPreview.value.text
 try {
  if (!navigator.clipboard?.writeText) throw new Error('Clipboard unavailable')
  await navigator.clipboard.writeText(text)
  copyNotice.value = 'Prompt disalin. Tempel sendiri ke chat AI pilihan Anda; belum ada data yang dikirim ke layanan AI.'
 } catch {
  promptTextarea.value?.focus(); promptTextarea.value?.select()
  copyNotice.value = 'Salin otomatis tidak tersedia. Teks sudah dipilih: tekan Ctrl+C (atau Command+C), lalu tempel ke chat AI pilihan Anda.'
 }
}
watch(researchSymbol, () => { void loadResearch() })
watch(() => trade.side, () => { trade.symbol = ''; tradeRequestId.value = '' })
watch(trade, () => { tradeRequestId.value = '' }, { deep: true, flush: 'sync' })
function holdingPayload() { return holdings.value.map(h => { const { stop, target, ...position } = h; return { ...position, ...(Number(stop) > 0 ? { stop: Number(stop) } : {}), ...(Number(target) > 0 ? { target: Number(target) } : {}) } }) }
watch(page, value => { if (value === 'holdings') void loadJournal(); if (value === 'research' && !researchSymbol.value) researchSymbol.value = availableSymbols.value[0] || '' })
async function refresh() { invalidatePrompt(); busy.value = 'refresh'; error.value = ''; notice.value = ''; try { data.value = await request('/api/refresh', {}); const planned = await request('/api/plan', { settings: { ...settings }, holdings: holdingPayload() }); if (data.value) { data.value.plans = planned.plans; if (planned.universe) data.value.universe = planned.universe; } await loadJournal(); notice.value = 'Data diperbarui. Pengaturan Anda tetap dipertahankan. Periksa tanggal observasi.' } catch (e: any) { error.value = e.message } finally { busy.value = '' } }
async function calculate(save = false) { if (save) invalidatePrompt(); busy.value = save ? 'save' : 'plan'; error.value = ''; notice.value = ''; try { const payload = await request(save ? '/api/portfolio' : '/api/plan', { settings: { ...settings }, holdings: holdingPayload() }); if (payload.plans && data.value) { data.value.plans = payload.plans; if (payload.universe) data.value.universe = payload.universe; } if (payload.settings) { Object.assign(settings, payload.settings); if (save && data.value) data.value.settings = { ...payload.settings } } if (payload.holdings) holdings.value = payload.holdings; if (save) await loadJournal(); notice.value = save ? 'Pengaturan dan portofolio tersimpan.' : 'Rencana dihitung ulang dengan batas risiko Anda.' } catch (e: any) { error.value = e.message } finally { busy.value = '' } }
function addHolding() { error.value = ''; const symbol = newHolding.symbol.trim().toUpperCase(); if (!/^[A-Z]{4}$/.test(symbol) || newHolding.shares <= 0 || !Number.isInteger(newHolding.shares) || newHolding.entryPrice <= 0 || newHolding.stop < 0 || newHolding.target < 0) { error.value = 'Isi kode saham 4 huruf, lembar positif, harga beli positif, dan stop yang valid.'; return } if (holdings.value.some(h => h.symbol === symbol)) { error.value = 'Saham sudah ada. Hapus posisi lama sebelum menggantinya.'; return } holdings.value.push({ symbol, shares: newHolding.shares, entryPrice: newHolding.entryPrice, ...(newHolding.stop > 0 ? { stop: newHolding.stop } : {}), ...(newHolding.target > 0 ? { target: newHolding.target } : {}), ...(newHolding.openedDate ? { openedDate: newHolding.openedDate } : {}) }); Object.assign(newHolding, { symbol: '', shares: 100, entryPrice: 0, stop: 0, target: 0, openedDate: '' }); notice.value = 'Posisi ditambahkan. Simpan untuk memperbarui rencana.' }
onMounted(load)
</script>

<template>
  <div class="workspace">
    <aside class="sidebar">
      <a class="brand" href="#" @click.prevent="page = 'overview'"><span class="brand-mark">s<span>↗</span></span><span>Swing<span class="brand-light">Lab</span><small>INDONESIA EQUITIES</small></span></a>
      <div class="workspace-label">PERSONAL WORKSPACE <span>01</span></div>
      <nav aria-label="Navigasi utama"><button v-for="item in nav" :key="item.id" :class="{ active: page === item.id }" @click="page = item.id"><span class="nav-icon">{{ item.icon }}</span>{{ item.label }}<span v-if="page === item.id" class="nav-dot"></span></button></nav>
      <div class="sidebar-note"><span class="tiny-label">METODE</span><h3>Rencana, bukan tebakan.</h3><p>Data harian. Aturan transparan. Risiko terukur.</p><span class="horizon-pill">3–15 sesi bursa</span></div>
      <div class="sidebar-footer"><span class="status-dot"></span> Mode edukasi & paper trading<small>Tidak terhubung ke broker</small></div>
    </aside>
    <main>
      <header class="topbar"><div class="breadcrumb">Workspace <span>/</span> <strong>{{ activeTitle }}</strong></div><div class="topbar-right"><span class="market-badge">IDX <i></i> END OF DAY</span><span class="avatar">P</span></div></header>
      <div class="content">
        <div class="page-heading"><div><div class="eyebrow">YOUR NEXT MOVE, WITH CONTEXT</div><h1>{{ page === 'overview' ? 'Pasar dalam perspektif.' : page === 'plans' ? 'Rencanakan risikonya.' : page === 'holdings' ? 'Kenali posisi Anda.' : page === 'research' ? 'Pahami di balik harga.' : page === 'prompts' ? 'Riset Anda, siap dibahas.' : 'Uji sebelum percaya.' }}</h1><p>{{ page === 'backtest' ? 'Simulasi historis dengan biaya, slippage, dan aturan eksekusi yang eksplisit.' : 'Ruang kerja pribadi untuk keputusan swing trading yang lebih terstruktur.' }}</p></div><button class="button secondary refresh-button" :disabled="!!busy" @click="refresh"><span :class="{ spinning: busy === 'refresh' }">↻</span> {{ busy === 'refresh' ? 'Memperbarui…' : 'Perbarui data' }}</button></div>
        <div v-if="error" class="message error" role="alert">{{ error }} <button v-if="!data" @click="load">Coba lagi</button></div>
        <div v-if="notice" class="message success" role="status">{{ notice }}</div>
        <div v-if="busy === 'loading'" class="loading-panel"><span class="loading-orbit"></span><h2>Menyiapkan ruang kerja</h2><p>Membaca data dan menghitung rencana…</p></div>
        <template v-else-if="data">
          <div class="source-line"><span class="source-tag"><span class="status-dot" :class="{ amber: data.source.status !== 'live' }"></span>{{ data.source.status === 'stale' ? 'Data belum terkini' : 'Snapshot tersimpan' }}</span><span>Observasi {{ date(data.source.asOf) }}</span><span class="source-description">{{ data.source.message }}</span></div>
          <template v-if="page === 'overview' || page === 'plans'">
            <section v-if="data.universe" class="scan-panel" aria-label="Cakupan pemindaian"><div class="scan-heading"><div><span class="tiny-label">UNIVERSE SCAN</span><h2>Lebih luas, tetap selektif.</h2></div><span class="subtle-pill">Batas {{ num(data.universe.limit) }} saham / scan</span></div><div class="scan-counts"><div><strong>{{ num(data.universe.discovered) }}</strong><span>Ditemukan</span></div><span class="scan-arrow">→</span><div><strong>{{ num(data.universe.selected) }}</strong><span>Dipilih</span></div><span class="scan-arrow">→</span><div><strong>{{ num(data.universe.scanned) }}</strong><span>Riwayat dipindai</span></div><span class="scan-arrow">→</span><div><strong>{{ num(data.universe.eligible) }}</strong><span>Data memenuhi syarat</span></div><span class="scan-arrow">→</span><div class="qualified-count"><strong>{{ num(data.universe.qualified) }}</strong><span>Setup lolos</span></div></div><p class="scan-coverage">{{ data.universe.coverage }} <span>Scan ini dibatasi; bukan pemindaian seluruh saham BEI.</span></p><details class="scan-details"><summary>Sumber & cakupan scan</summary><p>Sumber: {{ data.universe.source }} · Observasi {{ date(data.universe.asOf) }}</p><p v-if="data.universe.failed?.length">Gagal dimuat: {{ data.universe.failed.join(', ') }}. Saham tanpa data memadai tidak menghasilkan alokasi baru.</p><p v-else>Tidak ada kegagalan pengambilan riwayat yang dilaporkan dalam scan ini.</p></details></section><section class="stat-grid" aria-label="Ringkasan angka"><article class="stat-card"><span class="stat-label">IHSG <span>↗</span></span><strong>{{ num(latestIndex?.close) }}</strong><small :class="indexChange !== null && indexChange < 0 ? 'negative' : 'positive'">{{ indexChange !== null ? `${indexChange >= 0 ? '+' : ''}${num(indexChange)}%` : '—' }} <span>vs sesi sebelumnya</span></small></article><article class="stat-card"><span class="stat-label">Modal tersedia <span>Rp</span></span><strong>{{ idr(settings.cash) }}</strong><small>Dana tunai untuk rencana baru</small></article><article class="stat-card"><span class="stat-label">Kandidat BUY <span>◎</span></span><strong>{{ buyCount }} <em>/ {{ plans.length }}</em></strong><small>Hanya saat seluruh filter lolos</small></article><article class="stat-card"><span class="stat-label">Risiko rencana baru <span>◇</span></span><strong>{{ idr(plannedRisk) }}</strong><small>Stop bukan jaminan batas rugi</small></article></section>
            <div class="main-grid">
              <div class="main-column">
                <section v-if="page === 'overview'" class="panel chart-panel"><div class="panel-heading"><div><span class="tiny-label">MARKET PULSE</span><h2>Indeks Harga Saham Gabungan</h2></div><span class="subtle-pill">65 sesi terakhir</span></div><div v-if="indexPath" class="index-chart"><div class="chart-gridlines"><span></span><span></span><span></span></div><svg viewBox="0 0 760 180" role="img" aria-label="Grafik penutupan IHSG 65 sesi terakhir" preserveAspectRatio="none"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--accent)" stop-opacity=".17"/><stop offset="100%" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs><path :d="`${indexPath} L760,180 L0,180 Z`" fill="url(#chart-fill)"/><path :d="indexPath" fill="none" stroke="var(--accent)" stroke-width="2.3" vector-effect="non-scaling-stroke"/></svg></div><div v-else class="empty-inline">Data indeks belum tersedia.</div><div class="chart-footer"><span>{{ date(indexRows.slice(-65)[0]?.date) }}</span><span>Penutupan harian · Arjum</span><span>{{ date(latestIndex?.date) }}</span></div></section>
                <section class="panel plans-panel"><div class="panel-heading"><div><span class="tiny-label">TRADE PLAN TEKNIKAL</span><h2>{{ page === 'overview' ? 'Watchlist & rencana' : 'Rencana berdasarkan modal' }}</h2></div><span class="subtle-pill">{{ plans.length }} saham</span></div><p class="panel-description">Peringkat dan skor adalah heuristik untuk mengurutkan setup, bukan probabilitas keuntungan. Lolos setup belum tentu mendapat alokasi modal.</p><div class="plan-toolbar"><div class="plan-filter-group" role="group" aria-label="Filter rencana"><button :class="{ selected: planFilter === 'all' }" @click="planFilter = 'all'">Semua</button><button :class="{ selected: planFilter === 'qualified' }" @click="planFilter = 'qualified'">Setup lolos</button><button :class="{ selected: planFilter === 'held' }" @click="planFilter = 'held'">Dimiliki</button></div><label class="plan-search"><span class="sr-only">Cari kode saham</span><input v-model="planQuery" type="search" placeholder="Cari saham…" maxlength="12"/></label></div><p class="panel-description">BUY adalah pemicu simulasi. Hitung ulang ukuran pada harga eksekusi; lewati gap di atas 3%. WAIT adalah hasil yang valid.</p><div class="table-scroll"><table class="plans-table"><thead><tr><th>Peringkat / saham</th><th>Entry / stop</th><th>Target</th><th>Ukuran</th><th>Risiko</th></tr></thead><tbody><template v-for="plan in visiblePlans" :key="plan.symbol"><tr><td><span v-if="plan.rank" class="rank-label">#{{ plan.rank }}</span><button class="symbol symbol-link" @click="inspectSymbol(plan.symbol)" :aria-label="`Riset ${plan.symbol}`">{{ plan.symbol }}</button><small class="cell-secondary">Skor {{ plan.score == null ? '—' : num(plan.score) }} <span v-if="plan.rank != null">· lolos</span></small><span :class="['action-pill', plan.action.toLowerCase()]">{{ plan.action }}</span></td><td>{{ idr(plan.entry) }}<small class="cell-secondary">Stop {{ idr(plan.stop) }}</small></td><td>{{ idr(plan.target) }}</td><td>{{ num(plan.lots) }} lot<small class="cell-secondary">{{ idr(plan.estimatedCost) }}</small></td><td>{{ idr(plan.plannedRisk) }}</td></tr><tr class="reason-row"><td colspan="5"><div class="plan-data-facts"><span>{{ plan.historySessions ?? data.histories[plan.symbol]?.length ?? 0 }} sesi riwayat</span><span>Rata-rata nilai 20 sesi {{ compactIDR(plan.avgDailyValue) }}</span><span>Observasi {{ date(plan.asOf) }}</span></div><span class="reason-marker">↳</span>{{ plan.reasons.join(' · ') }}<div v-if="plan.rankingReasons?.length" class="ranking-reasons">Skor heuristik: {{ plan.rankingReasons.join(' · ') }}</div><span v-if="plan.expiry" class="expiry">Berlaku: {{ plan.expiry === 'NEXT_TRADING_SESSION_ONLY' ? 'sesi bursa berikutnya saja' : plan.expiry }}</span></td></tr></template></tbody></table></div><div v-if="!filteredPlans.length" class="empty-inline">{{ plans.length ? 'Tidak ada saham yang cocok dengan filter ini.' : 'Belum ada rencana. Periksa data lalu hitung ulang.' }}</div><div v-if="filteredPlans.length" class="plan-pagination"><span>{{ (planPage - 1) * pageSize + 1 }}–{{ Math.min(planPage * pageSize, filteredPlans.length) }} dari {{ filteredPlans.length }} saham</span><div><button :disabled="planPage <= 1" @click="planPage--" aria-label="Halaman sebelumnya">←</button><span>{{ planPage }} / {{ totalPlanPages }}</span><button :disabled="planPage >= totalPlanPages" @click="planPage++" aria-label="Halaman berikutnya">→</button></div></div><div class="panel-bottom"><span>Alokasi rencana BUY</span><strong>{{ idr(reserved) }}</strong></div></section>
              </div>
              <aside class="right-column"><section class="panel capital-panel"><div class="panel-heading"><div><span class="tiny-label">YOUR PARAMETERS</span><h2>Modal & risiko</h2></div><span class="settings-icon">⚙</span></div><form @submit.prevent="calculate()"><label class="field-label" for="cash">Dana tersedia <span>IDR</span></label><input id="cash" v-model.number="settings.cash" :disabled="journal.trades.length > 0" type="number" min="0" step="1" required class="capital-input"/><label class="field-label" for="equity">Total ekuitas portofolio <span>IDR</span></label><input id="equity" v-model.number="settings.equity" type="number" min="0" step="1" required/><p class="field-help">Total ekuitas sudah termasuk Dana tersedia + nilai pasar saham. Belum punya saham? Isi keduanya sama. Keduanya boleh 0.</p><button v-if="!holdings.length" type="button" class="text-button advanced-toggle" @click="settings.equity = settings.cash ?? 0">Samakan ekuitas dengan dana tersedia</button><div class="field-pair"><div><label class="field-label" for="risk">Risiko / trade (%)</label><input id="risk" v-model.number="settings.riskPct" type="number" min="0" max="5" step="0.01" required/></div><div><label class="field-label" for="cap">Batas posisi (%)</label><input id="cap" v-model.number="settings.maxPositionPct" type="number" min="1" max="100" step="1" required/></div></div><button type="button" class="text-button advanced-toggle" @click="showAdvanced = !showAdvanced">{{ showAdvanced ? '−' : '+' }} Pengaturan lanjutan</button><div v-if="showAdvanced" class="advanced-fields"><label v-for="field in [{key:'maxTotalRiskPct',label:'Total risiko terbuka (%)',step:.1},{key:'buyFeePct',label:'Biaya beli (%)',step:.01},{key:'sellFeePct',label:'Biaya jual (%)',step:.01},{key:'slippagePct',label:'Slippage (%)',step:.01},{key:'maxPositions',label:'Maksimal posisi',step:1},{key:'minDailyValue',label:'Minimal nilai harian (Rp)',step:100000000}]" :key="field.key" class="field-label">{{ field.label }}<input v-model.number="settings[field.key]" type="number" min="0" :step="field.step" required/></label></div><label>Batas waktu posisi baru<select v-model.number="settings.holdingSessions"><option v-for="sessions in 13" :key="sessions + 2" :value="sessions + 2">{{ sessions + 2 }} sesi bursa</option></select><small>Sesi beli = 1. Rencana keluar saat pembukaan sesi terakhir; stop/target dapat memicu keluar lebih awal. Simpan untuk transaksi dan prompt berikutnya.</small></label><button class="button primary full" :disabled="!!busy" type="submit">{{ busy === 'plan' ? 'Menghitung…' : 'Hitung rencana' }} <span>↗</span></button><button class="button quiet full" :disabled="!!busy" type="button" @click="calculate(true)">{{ busy === 'save' ? 'Menyimpan…' : 'Simpan pengaturan' }}</button></form></section><section class="insight-card"><span class="insight-icon">◇</span><span class="tiny-label">DISIPLIN LEBIH DULU</span><h3>Tidak selalu harus masuk pasar.</h3><p>Ukuran posisi dibatasi modal, risiko, likuiditas, dan total eksposur. Dana boleh tetap tunai.</p></section></aside>
            </div>
          </template>
          <template v-else-if="page === 'holdings'">
            <div class="portfolio-stack">
              <div v-if="journalError" class="message error" role="alert">{{ journalError }}</div>
              <div v-if="tradeNotice" class="message success" role="status">{{ tradeNotice }}</div>
              <section class="panel">
                <div class="panel-heading"><div><span class="tiny-label">PANTAU POSISI</span><h2>Yang perlu Anda perhatikan</h2></div><button class="button secondary" :disabled="journalBusy || !!busy" @click="loadJournal">Periksa posisi</button></div>
                <p class="panel-description">Pemantauan memakai snapshot harian tersimpan, bukan harga langsung. Perbarui data pasar untuk sesi baru. Peringatan muncul di aplikasi ini; tidak mengirim notifikasi ke luar aplikasi.</p>
                <div v-if="unseenAlerts.length" class="alert-list"><article v-for="alert in unseenAlerts" :key="alert.id" class="position-alert"><div><strong>{{ alert.symbol }} · Riwayat peringatan keluar</strong><p>{{ alert.reasons.join(' · ') }}</p><small>Observasi {{ date(alert.asOf) }} · {{ alert.strategyVersion }} · Berlaku {{ alert.expiry === 'NEXT_TRADING_SESSION_ONLY' ? 'sesi berikutnya saat sinyal dibuat' : alert.expiry }}. Periksa kartu posisi terbaru; peringatan lama bukan sinyal aktif.</small></div><button class="button secondary" :disabled="journalBusy" @click="acknowledgeAlert(alert.id)">Sudah dibaca</button></article></div>
                <p v-if="journal.valuationNote" class="panel-description">{{ journal.valuationNote }}</p><div class="monitor-grid"><article v-for="position in journal.monitoring" :key="position.symbol" class="monitor-card"><div class="monitor-heading"><button class="symbol symbol-link" @click="inspectSymbol(position.symbol)">{{ position.symbol }}</button><span :class="['action-pill', position.action.toLowerCase()]">{{ position.action }}</span></div><h3>{{ monitorLabel(position.action) }}</h3><p>{{ position.reasons.join(' · ') }}</p><dl><div><dt>Posisi</dt><dd>{{ num(position.shares) }} lembar</dd></div><div><dt>Stop / target tersimpan</dt><dd>{{ idr(holdings.find(h => h.symbol === position.symbol)?.stop) }} / {{ idr(holdings.find(h => h.symbol === position.symbol)?.target) }}</dd></div><div><dt>Batas waktu posisi</dt><dd>{{ position.holdingSessions ?? 15 }} sesi bursa</dd></div><div><dt>Sesi selesai sejak beli</dt><dd>{{ position.heldSessions == null ? 'Belum diketahui' : num(position.heldSessions) }}</dd></div><div><dt>Rencana keluar saat pembukaan</dt><dd>{{ date(position.plannedExitDate) }}</dd></div><div><dt>Status kalender</dt><dd>{{ calendarLabel(position.calendarStatus) }}</dd></div><div><dt>Harga observasi</dt><dd>{{ idr(position.price) }}</dd></div><div><dt>Estimasi hasil jual bersih</dt><dd>{{ idr(position.estimatedNet) }}</dd></div><div><dt>Estimasi biaya jual</dt><dd>{{ idr(position.estimatedFees) }}</dd></div></dl><small>Observasi {{ date(position.asOf) }} · {{ position.strategyVersion }}</small><small>Estimasi bukan harga eksekusi. {{ position.actionable ? 'Evaluasi ulang pada sesi berikutnya.' : 'Tidak ada instruksi keluar yang dapat ditindaklanjuti.' }}</small></article></div>
                <div v-if="!journal.monitoring.length" class="empty-inline">Belum ada posisi untuk dipantau. Catat transaksi yang sudah terjadi atau masukkan saldo posisi awal di bawah.</div>
              </section>
              <section class="panel">
                <div class="panel-heading"><div><span class="tiny-label">JURNAL TRANSAKSI</span><h2>Catat transaksi yang sudah terjadi</h2></div><span class="subtle-pill">Pencatatan manual</span></div>
                <p class="panel-description">Isi harga dan biaya aktual dari transaksi Anda. Ini memperbarui dana tersedia serta jumlah saham, termasuk penjualan sebagian. Gunakan dana yang sudah disimpan; formulir ini tidak mengeksekusi BUY atau SELL.</p>
                <form class="trade-form" @submit.prevent="recordTrade">
                  <label>Jenis transaksi<select v-model="trade.side" :disabled="journalBusy"><option value="BUY">Beli</option><option value="SELL">Jual</option></select></label>
                  <label>Saham<select v-model="trade.symbol" :disabled="journalBusy" required><option value="" disabled>Pilih saham</option><option v-for="symbol in tradeSymbols" :key="symbol">{{ symbol }}</option></select></label>
                  <label>Tanggal transaksi<input v-model="trade.date" :disabled="journalBusy" type="date" required/></label>
                  <label>Jumlah lembar<input v-model.number="trade.shares" :disabled="journalBusy" type="number" min="1" step="1" required/><small>Kelipatan 100, atau seluruh sisa posisi saat jual</small></label>
                  <label>Harga aktual / lembar<input v-model.number="trade.price" :disabled="journalBusy" type="number" min="1" step="1" required/></label>
                  <label>Total biaya aktual (Rp)<input v-model.number="trade.fee" :disabled="journalBusy" type="number" min="0" step="0.01" required/><small>Nominal total, bukan persentase</small></label>
                  <label v-if="trade.side === 'BUY'">Stop / lembar (opsional)<input v-model.number="trade.stop" :disabled="journalBusy" type="number" min="0" step="1"/></label>
                  <label v-if="trade.side === 'BUY'">Target / lembar (opsional)<input v-model.number="trade.target" :disabled="journalBusy" type="number" min="0" step="1"/></label>
                  <label v-if="trade.side === 'BUY' && !holdings.some(h => h.symbol === trade.symbol)">Batas waktu posisi<select v-model.number="trade.holdingSessions" :disabled="journalBusy"><option :value="0">Ikuti pengaturan tersimpan</option><option v-for="sessions in 13" :key="sessions + 2" :value="sessions + 2">{{ sessions + 2 }} sesi bursa</option></select><small>Dikunci saat posisi baru dicatat. Sesi beli dihitung sebagai sesi 1.</small></label>
                  <p v-if="trade.side === 'BUY' && holdings.some(h => h.symbol === trade.symbol)" class="trade-horizon-note">Penambahan saham memakai tanggal beli awal dan batas {{ holdings.find(h => h.symbol === trade.symbol)?.holdingSessions ?? 15 }} sesi posisi ini; hitungan tidak dimulai ulang.</p>
                  <button class="button primary" :disabled="journalBusy || !!busy" type="submit">{{ journalBusy ? 'Menyimpan…' : 'Catat transaksi' }}</button>
                </form>
                <div class="table-scroll"><table><thead><tr><th>Tanggal / saham</th><th>Jenis / jumlah</th><th>Harga aktual</th><th>Biaya</th><th>Perubahan tunai</th><th>Laba/rugi terealisasi</th></tr></thead><tbody><tr v-for="entry in journal.trades" :key="entry.id"><td><strong class="symbol">{{ entry.symbol }}</strong><small class="cell-secondary">{{ date(entry.date) }}</small></td><td>{{ entry.side === 'BUY' ? 'Beli' : 'Jual' }} · {{ num(entry.shares) }} lembar</td><td>{{ idr(entry.price) }}</td><td>{{ idr(entry.fee) }}</td><td>{{ idr(entry.cashDelta) }}</td><td>{{ idr(entry.realizedPnl) }}<small v-if="entry.side === 'SELL' && !entry.basisKnown" class="cell-secondary">Biaya perolehan belum lengkap</small></td></tr></tbody></table></div>
                <p v-if="journal.totalTrades" class="panel-description" style="margin-top:16px">{{ num(journal.totalTrades) }} transaksi tersimpan. Menampilkan maksimal 500 transaksi terbaru.</p><div v-if="!journal.trades.length" class="empty-inline">Belum ada transaksi tercatat. Posisi awal yang diimpor tidak otomatis menjadi transaksi jurnal.</div>
              </section>
              <details class="panel opening-holdings" :open="showOpeningHoldings" @toggle="showOpeningHoldings = ($event.target as HTMLDetailsElement).open"><summary>Saldo posisi awal & koreksi manual</summary><p class="panel-description">Gunakan untuk posisi yang sudah ada sebelum memakai jurnal. Mengubah saldo di sini tidak mencatat transaksi atau menghitung ulang dana tunai. Untuk pembelian dan penjualan baru, gunakan jurnal di atas.</p><section><div class="panel-heading"><div><span class="tiny-label">MANUAL PORTFOLIO</span><h2>Posisi yang Anda miliki</h2></div><button class="button primary" :disabled="!!busy" @click="calculate(true)">Simpan portofolio</button></div><p class="panel-description">SELL hanya berlaku untuk posisi tercatat. Pilihan saham mengikuti riwayat yang tersedia dan posisi yang sudah tercatat. Masukkan jumlah lembar, bukan jumlah lot.</p><p v-if="journal.trades.length" class="panel-description">Jurnal sudah aktif. Dana tunai dan jumlah posisi mengikuti transaksi; perubahan manual dibatasi pada stop, target, ekuitas, dan pengaturan risiko.</p><form v-if="!journal.trades.length" class="holding-form" @submit.prevent="addHolding"><label>Kode saham<select v-model="newHolding.symbol" required><option disabled value="">Pilih saham</option><option v-for="symbol in availableSymbols" :key="symbol">{{ symbol }}</option></select></label><label>Jumlah lembar<input v-model.number="newHolding.shares" type="number" min="1" step="1" required/></label><label>Harga beli / lembar<input v-model.number="newHolding.entryPrice" type="number" min="1" required/></label><label>Stop / lembar (opsional)<input v-model.number="newHolding.stop" type="number" min="0"/></label><label>Target / lembar (opsional)<input v-model.number="newHolding.target" type="number" min="0"/></label><label>Tanggal beli (opsional)<input v-model="newHolding.openedDate" type="date"/></label><button class="button secondary" type="submit">+ Tambah</button></form><div class="table-scroll"><table><thead><tr><th>Saham</th><th>Lembar</th><th>Harga beli</th><th>Stop</th><th>Target</th><th></th></tr></thead><tbody><tr v-for="(h, i) in holdings" :key="h.symbol"><td class="symbol">{{ h.symbol }}</td><td>{{ num(h.shares) }}</td><td>{{ idr(h.entryPrice) }}</td><td><input class="holding-level" v-model.number="h.stop" type="number" min="0" step="1" :aria-label="`Stop ${h.symbol}`" placeholder="Belum diisi"/></td><td><input class="holding-level" v-model.number="h.target" type="number" min="0" step="1" :aria-label="`Target ${h.symbol}`" placeholder="Belum diisi"/></td><td><button v-if="!journal.trades.length" class="text-button negative" @click="holdings.splice(i, 1)">Hapus</button></td></tr></tbody></table></div><div v-if="!holdings.length" class="empty-state"><span>▤</span><h3>Mulai dengan posisi pertama</h3><p>Portofolio kosong. Anda tetap dapat menghitung rencana pembelian.</p></div></section></details></div></template>
          <template v-else-if="page === 'prompts'">
            <section class="panel manual-prompt-panel">
              <div class="panel-heading"><div><span class="tiny-label">SALIN & TEMPEL SENDIRI</span><h2>Prompt dengan data saham Anda</h2></div><span class="subtle-pill">Tanpa API AI</span></div>
              <p class="panel-description">Pilih tujuan, tinjau isi, lalu salin ke chat AI pilihan Anda. Aplikasi menyusun teks dari data tersimpan dan tidak mengirimnya ke layanan AI. Balasan AI tidak mengubah rencana atau mengeksekusi transaksi.</p>
              <div class="prompt-workflow"><span>1 · Deep Research</span><span>2 · Starting Plan</span><span>3 · Daily Check-in</span></div>
              <form class="manual-prompt-form" @submit.prevent="generatePrompt">
                <fieldset class="prompt-mode-options"><legend>Tujuan pembahasan</legend><label v-for="mode in promptModes" :key="mode.id" :class="['prompt-mode', { selected: promptMode === mode.id }]"><input v-model="promptMode" type="radio" :value="mode.id" name="prompt-mode"/><span><strong>{{ mode.title }}</strong><small>{{ mode.description }}</small></span></label></fieldset>
                <div class="prompt-saved-note"><strong>Menggunakan pengaturan dan posisi terakhir yang disimpan.</strong><p>Batas posisi baru yang tersimpan: {{ data.settings.holdingSessions ?? 15 }} sesi bursa. Jika mengubah dana, risiko, atau batas waktu, simpan dulu di Trade planner, lalu buat ulang prompt. Posisi lama tetap mengikuti batas waktunya sendiri.</p><button class="text-button" type="button" @click="page = 'plans'">Buka Trade planner ↗</button></div>
                <fieldset v-if="promptMode !== 'daily-check-in'" class="prompt-stock-options"><legend>Saham yang akan dibahas · {{ promptSymbols.length }}/10</legend><label class="prompt-search">Cari kode saham<input v-model="promptQuery" type="search" placeholder="Contoh: ANTM" maxlength="12"/></label><div class="prompt-stock-grid"><label v-for="symbol in promptChoices" :key="symbol" :class="{ selected: promptSymbols.includes(symbol) }"><input type="checkbox" :checked="promptSymbols.includes(symbol)" :disabled="!promptSymbols.includes(symbol) && promptSymbols.length >= 10" @change="choosePromptSymbol(symbol)"/><span>{{ symbol }}</span></label></div><p v-if="!promptChoices.length" class="prompt-hint">Tidak ada kode yang cocok.</p><p class="prompt-hint">Pilih 1–10 saham. Memilih saham tidak berarti setup BUY-nya memenuhi syarat.</p></fieldset>
                <p v-else class="prompt-hint">Daily Check-in mengambil posisi yang sudah tersimpan, bukan daftar saham pilihan. Tanpa posisi, prompt akan menjelaskan bahwa belum ada posisi untuk ditinjau.</p>
                <fieldset class="prompt-sharing-options"><legend>Informasi yang akan masuk ke teks</legend><label class="prompt-checkbox"><input v-model="includePortfolio" type="checkbox"/><span><strong>Sertakan data portofolio pribadi</strong><small>Kas, ekuitas, batas risiko, posisi, dan ukuran rencana akan terlihat oleh layanan AI jika Anda menempelkannya di sana. Tanpa pilihan ini, data pribadi dan alokasi berdasarkan modal tidak disertakan.</small></span></label><label class="prompt-checkbox"><input v-model="includeResearch" type="checkbox"/><span><strong>Sertakan riset Arjum yang sudah tersimpan</strong><small>Termasuk konteks broker, keuangan, dan analisa provider bila tersedia. Membuat prompt tidak mengambil data baru atau menghabiskan kuota Arjum.</small></span></label></fieldset>
                <p v-if="promptMode === 'daily-check-in' && !includePortfolio" class="prompt-hint">Aktifkan data portofolio agar Daily Check-in dapat membahas posisi Anda; tanpa itu, hasil hanya berisi penjelasan prasyarat.</p>
                <div class="prompt-actions"><button class="button primary" :disabled="promptBusy || !!busy || (promptMode !== 'daily-check-in' && !promptSymbols.length)" type="submit">{{ promptBusy ? 'Menyusun…' : 'Buat pratinjau prompt' }}</button><span>Data lama atau tidak lengkap tetap diberi peringatan; AI tidak boleh mengarang angka.</span></div>
              </form>
            </section>
            <div v-if="promptError" class="message error" role="alert">{{ promptError }}</div>
            <section v-if="promptPreview" class="panel prompt-preview-panel">
              <div class="panel-heading"><div><span class="tiny-label">TINJAU SEBELUM MENYALIN</span><h2>Pratinjau prompt</h2></div><button class="button primary" :disabled="promptBusy" @click="copyPrompt">Salin prompt</button></div>
              <p class="panel-description">Dibuat {{ dateTime(promptPreview.generatedAt) }} · {{ promptPreview.symbols.length ? promptPreview.symbols.join(', ') : 'Tanpa saham' }} · {{ promptPreview.includesPortfolio ? 'Mengandung informasi portofolio pribadi' : 'Tanpa informasi portofolio pribadi' }}</p>
              <ul v-if="promptPreview.warnings.length" class="prompt-warnings"><li v-for="(warning, index) in promptPreview.warnings" :key="index">{{ warning }}</li></ul>
              <label class="prompt-preview-label">Teks yang akan disalin<textarea ref="promptTextarea" :value="promptPreview.text" readonly spellcheck="false" rows="22" aria-label="Teks prompt siap salin"></textarea></label>
              <p v-if="copyNotice" class="prompt-copy-notice" role="status">{{ copyNotice }}</p>
              <p class="panel-description">Sesudah menempel, minta AI menjelaskan pilihan dan kekurangan data. Periksa kembali angka di SwingLab. Tidak ada impor otomatis balasan AI atau pengiriman pesanan ke broker.</p>
            </section>
          </template>
          <template v-else-if="page === 'research'">
            <section class="panel research-intro"><div class="panel-heading"><div><span class="tiny-label">KONTEKS DARI ARJUM</span><h2>Arus transaksi & kesehatan keuangan</h2></div><span class="subtle-pill">Pendukung keputusan</span></div><p class="panel-description">Data ini membantu memahami saham, tetapi belum mengubah skor atau sinyal strategi. Arus beli bukan jaminan harga naik. Pilih saham untuk membaca hasil tersimpan; ambil data Arjum hanya saat diperlukan.</p><form class="research-controls" @submit.prevent="loadResearch(true)"><label>Saham<select v-model="researchSymbol" required><option v-for="symbol in availableSymbols" :key="symbol">{{ symbol }}</option></select></label><button class="button primary" :disabled="researchBusy" type="submit">{{ researchBusy ? 'Memuat…' : 'Ambil data Arjum' }}</button><span>Hasil disimpan sementara untuk menghemat kuota.</span></form></section>
            <div v-if="researchError" class="message error" role="alert">{{ researchError }}</div>
            <div v-if="researchBusy" class="empty-inline" role="status">Membaca konteks saham…</div>
            <section v-if="research" class="panel provider-analysis" aria-label="Analisa AI dari Arjum">
              <div class="panel-heading"><div><span class="tiny-label">ANALISA PROVIDER · {{ research.symbol }}</span><h2>Analisa AI · Arjum</h2></div><span class="subtle-pill">{{ researchStatus(providerAnalysis.status) }}</span></div>
              <p class="panel-description">Laporan dari Arjum, terpisah dari sinyal SwingLab. Label AI berasal dari provider; model dan metodenya belum diverifikasi. Rekomendasi atau tingkat harga dalam laporan ini tidak dipakai untuk menghitung alokasi Anda.</p>
              <p class="research-source">Tanggal laporan {{ date(providerAnalysis.asOf) }} · Diambil {{ dateTime(research.fetchedAt) }}</p>
              <div v-if="providerAnalysis.output" class="provider-analysis-text">{{ providerAnalysis.output }}</div>
              <div v-else class="empty-inline">Analisa untuk saham ini belum tersedia melalui API atau belum dimuat.</div>
              <ul class="research-notes"><li v-for="(note, index) in providerAnalysis.notes" :key="index">{{ note }}</li></ul>
              <a class="provider-analysis-source" href="https://stock.arjum.com/api-docs" target="_blank" rel="noopener noreferrer">Sumber: API analisa saham Arjum ↗</a>
            </section>
            <template v-if="research"><div class="research-source">{{ research.symbol }} · Diambil {{ dateTime(research.fetchedAt) }} · Sesi pasar diharapkan {{ date(research.expectedSession) }}</div><div class="research-grid"><section v-for="section in [{key:'broker',title:'Broker & arus investor',label:'SIAPA YANG BERTRANSAKSI'}, {key:'financial',title:'Kesehatan keuangan',label:'KONDISI PERUSAHAAN'}]" :key="section.key" class="panel"><div class="panel-heading"><div><span class="tiny-label">{{ section.label }}</span><h2>{{ section.title }}</h2></div><span class="subtle-pill">{{ researchStatus(research[section.key].status) }}</span></div><p class="panel-description">Tanggal data {{ date(research[section.key].asOf) }}</p><dl class="research-facts"><div v-for="(item, index) in research[section.key].items" :key="index" :class="['research-fact', item.tone]"><dt>{{ item.label }}</dt><dd>{{ item.value }}</dd></div></dl><div v-if="!research[section.key].items.length" class="empty-inline">Belum ada data yang dapat ditampilkan untuk bagian ini.</div><ul class="research-notes"><li v-for="(note, index) in research[section.key].notes" :key="index">{{ note }}</li></ul></section></div><ul v-if="research.notes.length" class="research-notes research-general"><li v-for="(note, index) in research.notes" :key="index">{{ note }}</li></ul></template>
          </template>
          <template v-else-if="page === 'backtest'"><section class="panel"><div class="panel-heading"><div><span class="tiny-label">RESEARCH, NOT A PROMISE</span><h2>Hasil pengujian historis</h2></div><span class="subtle-pill">Eksploratif</span></div><div class="research-warning"><strong>Belum merupakan bukti strategi yang tervalidasi.</strong><p>Laporan historis ini memakai empat saham dan versi strategi yang tercantum di bawah. Hasilnya bukan validasi untuk universe scan atau pemeringkatan baru. Penyesuaian aksi korporasi dan survivorship bias tetap menjadi keterbatasan.</p></div><template v-if="report"><p class="panel-description">Universe: {{ report.universe?.join(', ') }} · Laporan {{ date(report.generatedAt) }} · {{ report.strategyVersion }}</p><div class="period-tabs"><button :class="{ selected: testPeriod === 'holdout' }" @click="testPeriod = 'holdout'">Evaluasi holdout</button><button :class="{ selected: testPeriod === 'development' }" @click="testPeriod = 'development'">Periode pengembangan</button></div><template v-if="testResult"><div class="backtest-date">{{ date(testResult.startDate) }} — {{ date(testResult.endDate) }}</div><div class="backtest-stats"><article><span>Return bersih</span><strong :class="testResult.totalReturnPct < 0 ? 'negative' : 'positive'">{{ num(testResult.totalReturnPct) }}%</strong><small>Setelah biaya & slippage</small></article><article><span>Drawdown maksimum</span><strong>{{ num(testResult.maxDrawdownPct) }}%</strong><small>Penurunan dari puncak ekuitas</small></article><article><span>Transaksi selesai</span><strong>{{ num(testResult.tradeCount) }}</strong><small>Win rate {{ num(testResult.winRatePct) }}%</small></article><article><span>Benchmark</span><strong>{{ num(testResult.benchmarkReturnPct) }}%</strong><small>Modal awal yang sebanding</small></article></div><div class="backtest-chart-heading"><h3>Pertumbuhan ekuitas</h3><span><i class="strategy-legend"></i> Strategi <i class="benchmark-legend"></i> Benchmark</span></div><div v-if="performancePaths.strategy" class="index-chart backtest-chart"><div class="chart-gridlines"><span></span><span></span><span></span></div><svg viewBox="0 0 760 180" role="img" aria-label="Perbandingan kurva ekuitas strategi dan benchmark" preserveAspectRatio="none"><path :d="performancePaths.benchmark" fill="none" stroke="var(--muted)" stroke-width="1.5" stroke-dasharray="5 4" vector-effect="non-scaling-stroke"/><path :d="performancePaths.strategy" fill="none" stroke="var(--accent)" stroke-width="2.3" vector-effect="non-scaling-stroke"/></svg></div><div class="backtest-details"><span>Ekuitas akhir <strong>{{ idr(testResult.finalEquity) }}</strong></span><span>Ekspektansi / trade <strong>{{ idr(testResult.expectancy) }}</strong></span><span>Entri dilewati <strong>{{ num(testResult.skippedEntries) }}</strong></span></div><div class="table-scroll"><table><thead><tr><th>Saham</th><th>Masuk → keluar</th><th>Lembar</th><th>P/L bersih</th><th>Alasan keluar</th></tr></thead><tbody><tr v-for="(trade, i) in [...(testResult.trades || [])].reverse().slice(0, 30)" :key="i"><td class="symbol">{{ trade.symbol }}</td><td>{{ date(trade.entryDate) }}<small class="cell-secondary">{{ date(trade.exitDate) }}</small></td><td>{{ num(trade.shares) }}</td><td :class="trade.netPnl < 0 ? 'negative' : 'positive'">{{ idr(trade.netPnl) }}</td><td>{{ trade.reason }}</td></tr></tbody></table></div><div v-if="!testResult.trades?.length" class="empty-inline">Tidak ada transaksi pada periode ini. Hasil nol transaksi tidak membuktikan kualitas strategi.</div><div v-if="testResult.openPositions?.length" class="open-positions-note">{{ testResult.openPositions.length }} posisi masih terbuka pada akhir periode. Ekuitas akhir memasukkan nilai pasar posisi ini; statistik transaksi selesai tidak memasukkannya.</div><p class="panel-description" style="margin-top: 16px">Menampilkan maksimal 30 transaksi terakhir. Seluruh transaksi tersedia dalam laporan lokal.</p></template><section v-if="report.sensitivity?.length" class="sensitivity-panel"><h3>Sensitivitas biaya · periode evaluasi</h3><p class="panel-description">Aturan tetap; bukan pencarian parameter terbaik. Modal simulasi Rp10.000.000, terpisah dari pengaturan planner.</p><div class="table-scroll"><table><thead><tr><th>Skenario</th><th>Return bersih</th><th>Drawdown</th><th>Transaksi</th></tr></thead><tbody><tr v-for="scenario in report.sensitivity" :key="scenario.name"><td>{{ scenario.name }}</td><td>{{ num(scenario.returnPct) }}%</td><td>{{ num(scenario.maxDrawdownPct) }}%</td><td>{{ scenario.trades }}</td></tr></tbody></table></div></section><details class="assumptions"><summary>Asumsi & keterbatasan pengujian</summary><ul><li v-for="(warning, i) in [...(report.warnings || []), ...(report.assumptions || [])]" :key="i">{{ warning }}</li></ul></details></template><div v-else class="empty-state"><span>⌁</span><h3>Belum ada laporan backtest</h3><p>Jalankan pengujian lokal terlebih dahulu. Hasil akan tampil di sini setelah tersedia.</p></div></section></template>
          <footer class="content-footer"><span>SwingLab <span class="footer-divider">/</span> Personal research workspace</span><span>Data: Arjum · Bukan instruksi transaksi otomatis</span></footer>
        </template>
      </div>
    </main>
  </div>
</template>












